/* -------------------------------------------------------------------------- */
/* Icons                                                                       */
/* -------------------------------------------------------------------------- */

function LockIcon() {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      className="w-3 h-3 shrink-0"
      aria-hidden="true"
    >
      <rect x="5" y="10" width="14" height="10" rx="2" />
      <path d="M8 10V7a4 4 0 0 1 8 0v3" />
    </svg>
  )
}

function CheckIcon() {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      className="w-3 h-3 shrink-0"
      aria-hidden="true"
    >
      <path d="m5 12 4 4L19 6" />
    </svg>
  )
}

/* -------------------------------------------------------------------------- */
/* Tool pill                                                                   */
/* -------------------------------------------------------------------------- */

function ToolPill({ tool }) {
  return (
    <span
      className={[
        'inline-flex items-center gap-2',
        'h-9 px-3',
        'rounded-full',
        'border',
        'whitespace-nowrap',
        'select-none',
        'transition-colors',
        tool.access
          ? 'bg-white/[0.025] border-white/10 text-white/65'
          : 'bg-transparent border-white/[0.055] text-white/20',
      ].join(' ')}
    >
      {/* SVG / image URL slot */}
      <span
        className={[
          'w-4 h-4 shrink-0',
          'flex items-center justify-center',
          'overflow-hidden',
          !tool.icon ? 'rounded-[4px] bg-white/[0.07]' : '',
        ].join(' ')}
      >
        {tool.icon ? (
          <img
            src={tool.icon}
            alt=""
            aria-hidden="true"
            loading="lazy"
            decoding="async"
            className={[
              'w-full h-full object-contain',
              !tool.access ? 'opacity-30 grayscale' : '',
            ].join(' ')}
          />
        ) : null}
      </span>

      <span className="text-[13px] leading-none">
        {tool.name}
      </span>

      {tool.access ? (
        <span
          className="text-emerald-400/80"
          aria-label="Readable"
          title="Readable"
        >
          <CheckIcon />
        </span>
      ) : (
        <span
          className="text-white/20"
          aria-label="No access"
          title="No access"
        >
          <LockIcon />
        </span>
      )}
    </span>
  )
}

/* -------------------------------------------------------------------------- */
/* Person card                                                                 */
/* -------------------------------------------------------------------------- */

function PersonAccessCard({ person }) {
  return (
    <article
      className="
        w-full
        rounded-[18px]
        border border-white/[0.075]
        bg-[#151515]
        px-8
        py-7
      "
    >
      {/* Person */}
      <div className="flex items-center gap-3.5 mb-5">
        <div
          className="
            w-11 h-11
            shrink-0
            rounded-full
            border border-white/10
            bg-white/[0.035]
            flex items-center justify-center
            text-[11px]
            tracking-wide
            text-white/55
          "
        >
          {person.initials}
        </div>

        <div className="min-w-0">
          <p className="text-[15px] font-semibold leading-tight text-white/90">
            {person.name}
          </p>

          <p className="mt-1 text-[13px] leading-none text-white/35">
            {person.role}
          </p>
        </div>
      </div>

      {/* Tools */}
      <div className="flex flex-wrap gap-2 mb-6">
        {person.tools.map((tool) => (
          <ToolPill
            key={`${person.name}-${tool.name}`}
            tool={tool}
          />
        ))}
      </div>

      {/* Description */}
      <p className="text-[13px] leading-[1.65] text-white/45 max-w-[570px]">
        {person.note}
      </p>
    </article>
  )
}

/* -------------------------------------------------------------------------- */
/* Section                                                                     */
/* -------------------------------------------------------------------------- */

export default function Permissions() {
  return (
    <section
      className="
      mx-auto
        w-[100rem]
        px-6
        sm:px-8
        py-24
        lg:py-28
      "
    >
      <div
        className="
          max-w-[1200px]
          mx-auto
          grid
          lg:grid-cols-[minmax(0,0.92fr)_minmax(0,1fr)]
          gap-14
          xl:gap-[88px]
          items-center
        "
      >
        {/* ---------------------------------------------------------------- */}
        {/* Left side                                                        */}
        {/* ---------------------------------------------------------------- */}

        <div className="max-w-[550px]">
          <p
            className="
              text-[10px]
              sm:text-[11px]
              uppercase
              tracking-[0.32em]
              text-white/35
              mb-7
            "
          >
            Permissions
          </p>

          <h2
            className="
             text-[2.5rem]
              leading-[1.12]
              font-semibold
              tracking-[-0.035em]
              text-white
              mb-7
            "
          >
            Nobody sees anything
            <br className="hidden sm:block" />
            {' '}they couldn't already see
          </h2>

          <p
            className="
              text-[17px]
              sm:text-[18px]
              leading-[1.85]
              text-white/55
              max-w-[550px]
            "
          >
            Your company already decided who can see what - Drive folder
            permissions, private Slack channels, Notion page access.{' '}

            <span className="text-white/90 font-semibold">
              Unabyss inherits it:
            </span>{' '}

            each person connects their own accounts, so their context is
            built from exactly what they can already open, and nothing more.
          </p>
        </div>

        {/* ---------------------------------------------------------------- */}
        {/* Right side                                                       */}
        {/* ---------------------------------------------------------------- */}

        <div className="flex flex-col gap-[18px] w-full">
          {PEOPLE_ACCESS.map((person) => (
            <PersonAccessCard
              key={person.name}
              person={person}
            />
          ))}
        </div>
      </div>
    </section>
  )
}